import type { ReadinessStage } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';

interface ReadinessStageEntry {
  label: string;
  variant: BadgeVariants;
}

export const readinessStageConfig: Record<ReadinessStage, ReadinessStageEntry> = {
  unregistered: { label: 'Unregistered', variant: 'default' },
  registered_unconfirmed: { label: 'Registered (unconfirmed)', variant: 'info' },
  application_incomplete: { label: 'Application incomplete', variant: 'warning' },
  documents_missing: { label: 'Documents missing', variant: 'warning' },
  bio_missing: { label: 'Bio missing', variant: 'warning' },
  avatar_missing: { label: 'Avatar missing', variant: 'warning' },
  voice_sample_missing: { label: 'Verification sample missing', variant: 'warning' },
  branch_onboarding_pending: { label: 'Branch onboarding pending', variant: 'info' },
  application_ready: { label: 'Application ready', variant: 'info' },
  // Labeled "Onboarded" rather than the stage key: the stage is the person's overall journey rung (every
  // onboarding step done, has applied somewhere, free to work). "Applied" reads as project-scoped on project
  // pages, where the eligible list excludes that project's own applicants - the one thing it never means.
  applied: { label: 'Onboarded', variant: 'success' },
  assigned_active: { label: 'Assigned active', variant: 'success' },
  unavailable_until_project_end: { label: 'Unavailable until project end', variant: 'violet' },
};

const defaultEntry: ReadinessStageEntry = { label: '', variant: 'default' };

export function getReadinessStage(stage: ReadinessStage): ReadinessStageEntry {
  return readinessStageConfig[stage] ?? { ...defaultEntry, label: snakeCaseToCapitalizedCase(stage) };
}

// Applied-or-beyond stages. General targets only cold/in-progress, so the General tab gates personas resolving to these - keyed on readiness_stage so new onboarded stages gate automatically.
export const fullyOnboardedReadinessStages = new Set<ReadinessStage>([
  'applied',
  'assigned_active',
  'unavailable_until_project_end',
]);

export const readinessStageValues = Object.keys(readinessStageConfig) as [ReadinessStage, ...ReadinessStage[]];

export const readinessStageOptions: SelectItem<ReadinessStage>[] = Object.entries(readinessStageConfig).map(
  ([value, { label }]) => ({ name: label, value: value as ReadinessStage })
);
